import React, { forwardRef, InputHTMLAttributes } from 'react';
import { cn } from '../../internal/cn';

/* ============================================
 * Checkbox
 * Figma Source: 03_Components > checkbox
 * (props 는 staff Checkbox 와 동일 — drop-in 대체용)
 *
 * Size: sm(16px, icon 12) | default(18px, icon 14), radius 4
 * States: default(흰 bg + gray-300 border) | active(primary bg + 흰 체크) | indeterminate(primary bg + 흰 dash)
 * ============================================ */

export interface CheckboxProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'onChange' | 'size'> {
  label?: string;
  checked?: boolean;
  /** 부분 선택 (테이블 헤더) */
  indeterminate?: boolean;
  onChange?: (checked: boolean) => void;
  disabled?: boolean;
  /** sm: 16px, default: 18px */
  size?: 'sm' | 'default';
  'aria-label'?: string;
}

const BOX_SIZE = {
  sm: { box: 'w-4 h-4', icon: 12 },
  default: { box: 'w-[18px] h-[18px]', icon: 14 },
} as const;

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      label,
      checked = false,
      indeterminate = false,
      onChange,
      disabled = false,
      size = 'default',
      className,
      id,
      ...rest
    },
    ref
  ) => {
    const inputRef = React.useRef<HTMLInputElement | null>(null);

    React.useEffect(() => {
      const el = inputRef.current;
      if (el) el.indeterminate = indeterminate;
    }, [indeterminate]);

    const handleRef = (node: HTMLInputElement | null) => {
      inputRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) (ref as React.MutableRefObject<HTMLInputElement | null>).current = node;
    };

    const isActive = checked || indeterminate;
    const sizeConfig = BOX_SIZE[size];

    return (
      <label
        className={cn(
          'inline-flex items-center gap-2 select-none font-sans',
          disabled ? 'cursor-not-allowed' : 'cursor-pointer',
          className
        )}
      >
        <span className="relative inline-flex items-center justify-center">
          <input
            ref={handleRef}
            id={id}
            type="checkbox"
            className={cn(
              'relative appearance-none cursor-pointer flex-shrink-0 border rounded-[4px] transition-all duration-150',
              sizeConfig.box,
              isActive
                ? 'bg-primary border-primary hover:bg-primary-hover'
                : 'bg-surface border-border-hover hover:bg-surface-muted',
              'focus-visible:shadow-[0_0_0_3px_rgba(38,57,73,0.08)] focus-visible:outline-none',
              disabled && 'opacity-50 cursor-not-allowed pointer-events-none'
            )}
            checked={checked}
            disabled={disabled}
            onChange={(e) => onChange?.(e.target.checked)}
            {...rest}
          />
          {isActive && (
            <span className="absolute inset-0 flex items-center justify-center pointer-events-none text-white">
              {indeterminate ? (
                <svg width={sizeConfig.icon} height={sizeConfig.icon} viewBox="0 0 14 14" fill="none">
                  <rect x="2" y="6" width="10" height="2" rx="1" fill="currentColor" />
                </svg>
              ) : (
                <svg width={sizeConfig.icon} height={sizeConfig.icon} viewBox="0 0 14 14" fill="none">
                  <path d="M3 7L5.5 9.5L11 4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              )}
            </span>
          )}
        </span>
        {label && (
          <span className={cn('text-base-medium', disabled ? 'text-gray-400' : 'text-gray-950')}>
            {label}
          </span>
        )}
      </label>
    );
  }
);

Checkbox.displayName = 'Checkbox';
