import React, { forwardRef } from 'react';
import type { ButtonProps, ButtonSize, ButtonVariant } from './Button.types';

import { cn } from '../../internal/cn';

/* ============================================
 * Button
 * Figma Source: 03_Components > Button (Button 30 / Button 36)
 *
 * Variants: primary | secondary | ghost | danger | etc
 * Sizes: sm(30px/12px/r6) | md(36px/14px/r8) | lg(44px) — lg는 Figma 미정의(기존 유지)
 * States: Default · Hover · Active · Disabled · Loading · LeadingIcon · IconOnly
 *
 * 화면당 Primary 1개만. Danger는 확인 모달 필수.
 * gap 4px · icon md 20 / sm 16 · Focus: 3px ring
 * Hover(danger·etc): 20% 어둡게 = base*0.8 (Figma 오버레이 환산값)
 * Loading: 버튼 disabled + Spinner + label 유지 (bg는 disabled 스타일)
 * ============================================ */

const BASE =
  'inline-flex items-center justify-center gap-1 font-sans whitespace-nowrap ' +
  'transition-all duration-150 cursor-pointer select-none ' +
  'focus-visible:outline-none focus-visible:shadow-[0_0_0_3px_rgba(38,57,73,0.08)]';

const VARIANT: Record<ButtonVariant, string> = {
  primary:
    'bg-primary text-white ' +
    'hover:bg-primary-hover ' +
    'disabled:bg-gray-400 disabled:text-white',
  secondary:
    'bg-surface text-gray-600 border border-border ' +
    'disabled:text-gray-400',
  ghost:
    'bg-transparent text-gray-600 ' +
    'disabled:text-gray-400',
  danger:
    'bg-error text-white border border-error ' +
    'hover:bg-[#b01e1e] ' +
    'active:bg-error-subtle active:border-[rgba(220,38,38,0.1)] active:text-error ' +
    'disabled:bg-error-subtle disabled:border-[rgba(220,38,38,0.1)] disabled:text-[rgba(220,38,38,0.3)]',
  etc:
    'bg-nav-accent text-white ' +
    'hover:bg-[#2ea087] ' +
    'disabled:bg-gray-400 disabled:text-white',
};

const SIZE: Record<ButtonSize, string> = {
  sm: 'h-[30px] px-3 text-xs-medium rounded-[6px]',
  md: 'h-9 px-4 text-base-medium rounded-[8px]',
};

/** IconOnly — 정사각(height = width), px 패딩 없음 */
const ICON_ONLY_SIZE: Record<ButtonSize, string> = {
  sm: 'size-[30px] rounded-[6px]',
  md: 'size-9 rounded-[8px]',
};

const DISABLED = 'cursor-not-allowed pointer-events-none';

const Spinner: React.FC<{ size: ButtonSize }> = ({ size }) => {
  const dim = size === 'sm' ? 'w-3 h-3' : 'w-4 h-4';
  return (
    <span
      aria-hidden="true"
      className={`${dim} rounded-full border-2 border-current border-t-transparent animate-spin`}
    />
  );
};

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  {
    variant = 'primary',
    size = 'md',
    disabled = false,
    loading = false,
    fullWidth = false,
    iconOnly = false,
    leadingIcon,
    trailingIcon,
    children,
    className,
    ...rest
  },
  ref
) {
  const isDisabled = disabled || loading;

  // IconOnly — 정사각, 텍스트 없이 아이콘(또는 children)만 중앙 렌더
  if (iconOnly) {
    return (
      <button
        ref={ref}
        className={cn(
          BASE,
          VARIANT[variant],
          ICON_ONLY_SIZE[size],
          isDisabled && DISABLED,
          className
        )}
        disabled={isDisabled}
        {...rest}
      >
        {loading ? (
          <Spinner size={size} />
        ) : (
          <span aria-hidden="true" className="flex items-center">
            {leadingIcon ?? children}
          </span>
        )}
      </button>
    );
  }

  return (
    <button
      ref={ref}
      className={cn(
        BASE,
        VARIANT[variant],
        SIZE[size],
        isDisabled && DISABLED,
        fullWidth && 'w-full',
        className
      )}
      disabled={isDisabled}
      {...rest}
    >
      {loading ? (
        <Spinner size={size} />
      ) : (
        leadingIcon && (
          <span aria-hidden="true" className="flex items-center">
            {leadingIcon}
          </span>
        )
      )}
      {children != null && <span>{children}</span>}
      {!loading && trailingIcon && (
        <span aria-hidden="true" className="flex items-center">
          {trailingIcon}
        </span>
      )}
    </button>
  );
});

Button.displayName = 'Button';
