import React from 'react';
import { Icon } from '../Icon';

/* ═══════════════════════════════════════
   Component: AdminGNB
   Figma Source: 06_LNB_GNB > GNB Specifications
   Role: Global Navigation Bar (상단 바)
   ═══════════════════════════════════════
   Specs:
     Height: 64px (--gnb-height)
     Width: calc(100% - 210px)
     Position: fixed
     Background: --nav-top-bg (#223240)
     Item Height: 36px
   ═══════════════════════════════════════ */

export interface GNBNavItem {
  id: string;
  label: string;
}

export interface AdminGNBProps {
  /** 메뉴 아이템 목록 */
  items?: GNBNavItem[];
  /** 활성화된 아이템 ID */
  activeItemId?: string;
  /** 아이템 클릭 핸들러 */
  onItemClick?: (itemId: string) => void;
  /** 토글 버튼 표시 여부 */
  showCollapseButton?: boolean;
  /** 토글 버튼 클릭 핸들러 */
  onCollapseClick?: () => void;
  /** LNB 접힘 상태 */
  collapsed?: boolean;
}

export const AdminGNB: React.FC<AdminGNBProps> = ({
  items = [],
  activeItemId,
  onItemClick,
  showCollapseButton = true,
  onCollapseClick,
  collapsed = false,
}) => {
  return (
    <header
      className={[
        'fixed right-0 top-0 z-[100] flex h-gnb items-center gap-6',
        'bg-nav-top-bg px-6 transition-[left] duration-200 ease-in-out',
        collapsed ? 'left-0' : 'left-lnb',
      ].join(' ')}
      role="banner"
      aria-label="상단 네비게이션"
    >
      {/* Collapse Toggle */}
      {showCollapseButton && (
        <button
          className={[
            'flex size-8 cursor-pointer items-center justify-center',
            'rounded-sm border-none bg-transparent text-white',
            'transition-colors duration-150 hover:bg-white/[0.08]',
          ].join(' ')}
          onClick={onCollapseClick}
          aria-label="사이드바 토글"
        >
          <Icon
            name={collapsed ? 'keyboard_double_arrow_right' : 'keyboard_double_arrow_left'}
            size={32}
            decorative
          />
        </button>
      )}

      {/* Nav Items — Figma 정본: 모든 item 동일 색상 (active 시각화 없음) */}
      <nav className="flex items-center gap-[50px]" role="navigation" aria-label="빠른 메뉴">
        {items.map((item) => {
          const isActive = item.id === activeItemId;
          return (
            <button
              key={item.id}
              className={[
                'cursor-pointer whitespace-nowrap border-none bg-transparent px-0',
                'text-lg-medium text-nav-text-muted tracking-[-0.16px]',
                'transition-colors duration-150 hover:text-white',
              ].join(' ')}
              onClick={() => onItemClick?.(item.id)}
              aria-current={isActive ? 'page' : undefined}
            >
              {item.label}
            </button>
          );
        })}
      </nav>
    </header>
  );
};
