import { create } from 'zustand';
import type { ModalEntry, ModalOpenOptions } from './Modal.types';

/* ============================================
 * modalStore — imperative 모달 스택 (zustand)
 *
 * 외부 어디서든 `modal.open(...)` 으로 모달을 띄운다.
 * 실제 렌더는 <ModalRoot /> 가 이 스토어 stack 을 구독해 선언형 <Modal> 로 그린다.
 * ============================================ */

interface ModalState {
  stack: ModalEntry[];
  /** 스택에 모달 추가 후 id 반환 */
  push: (options: ModalOpenOptions) => string;
  /** id 로 모달 제거 */
  closeById: (id: string) => void;
}

const uid = () => Math.random().toString(36).slice(2, 10);

export const useModalStore = create<ModalState>((set) => ({
  stack: [],
  push: (options) => {
    const id = uid();
    set((state) => ({ stack: [...state.stack, { id, options }] }));
    return id;
  },
  closeById: (id) => {
    set((state) => ({ stack: state.stack.filter((e) => e.id !== id) }));
  },
}));

/** 모달 제어 핸들 — open() 반환값. */
export interface ModalHandle {
  id: string;
  close: () => void;
}

export const modal = {
  /**
   * 모달을 띄운다. 반환된 핸들의 `close()` 로 직접 닫을 수 있다.
   * 닫힘(어떤 사유든) 시 options.onClose 가 한 번 호출된다.
   */
  open(options: ModalOpenOptions): ModalHandle {
    const id = useModalStore.getState().push(options);
    return {
      id,
      close: () => useModalStore.getState().closeById(id),
    };
  },

  /** id 로 모달을 닫는다. */
  close(id: string): void {
    useModalStore.getState().closeById(id);
  },

  /**
   * 확인/취소 모달. Primary→true, Secondary/X/ESC→false 로 resolve.
   */
  confirm(options: ModalOpenOptions): Promise<boolean> {
    return new Promise<boolean>((resolve) => {
      const handle = modal.open({
        primaryLabel: '확인',
        secondaryLabel: '취소',
        ...options,
        onPrimary: () => {
          resolve(true);
          handle.close();
        },
        onSecondary: () => {
          resolve(false);
          handle.close();
        },
        // X/ESC/backdrop 로 닫혀도 false 로 정리(Promise 는 멱등 → 중복 resolve 무시).
        onClose: () => resolve(false),
      });
    });
  },

  /**
   * 알림 모달. Primary 또는 닫기 시 resolve.
   */
  alert(options: ModalOpenOptions): Promise<void> {
    return new Promise<void>((resolve) => {
      const handle = modal.open({
        primaryLabel: '확인',
        ...options,
        onPrimary: () => {
          resolve();
          handle.close();
        },
        onClose: () => resolve(),
      });
    });
  },
};
