import React, { forwardRef } from 'react';
import type { InputFieldProps } from './InputField.types';
import { cn } from '../../internal/cn';

/* ============================================
 * InputField
 * Figma Source: 03_Components > InputField
 * (props 는 staff Input 과 동일 — drop-in 대체용)
 *
 * Size: 36px (단일)
 * States: Default · Hover · Focus · Filled · Error · Success · Disabled · ReadOnly
 *
 * Anatomy: Label(13px Regular) + Field(36px, r8) + (status icon 18 / message 12)
 * Message priority: Error > Success > Helper
 *
 * Figma 토큰:
 *   label: gray-600 (disabled gray-400) · 13px Regular
 *   border default: border(#e4e4e7) · hover: primary-hover(#1f3040)
 *   focus: border 중립 유지 + ring 3px rgba(38,57,73,0.08)
 *   error border: status/error · success border: status/success
 *   disabled/readOnly bg: gray-50 · field text: gray-900 · placeholder: gray-400
 * ============================================ */

const FIELD_BASE =
  'w-full h-9 px-3 text-base-regular rounded-[8px] border bg-surface text-gray-900 font-sans ' +
  'placeholder:text-gray-400 ' +
  'transition-all duration-200 outline-none ' +
  'hover:border-primary-hover ' +
  'focus:shadow-[0_0_0_3px_rgba(38,57,73,0.08)]';

const FIELD_STATUS: Record<NonNullable<InputFieldProps['status']>, string> = {
  default: 'border-border',
  error:   'border-error hover:border-error focus:border-error focus:shadow-[0_0_0_3px_rgba(220,38,38,0.08)]',
  success: 'border-success hover:border-success focus:border-success focus:shadow-[0_0_0_3px_rgba(22,163,74,0.08)]',
};

/* ── In-field status icons (18px) ── */
const ErrorIcon: React.FC = () => (
  <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true">
    <circle cx="9" cy="9" r="8" stroke="currentColor" strokeWidth="1.5" />
    <path d="M9 5.5v4M9 12v.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
  </svg>
);

const SuccessIcon: React.FC = () => (
  <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true">
    <circle cx="9" cy="9" r="8" stroke="currentColor" strokeWidth="1.5" />
    <path d="M6 9l2 2 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

/* ── Message icons (12px) ── */
const ErrorMsgIcon: React.FC = () => (
  <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true" className="flex-shrink-0">
    <circle cx="6" cy="6" r="5.25" stroke="currentColor" strokeWidth="1.5" />
    <path d="M6 3.5v3M6 8.5v.25" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
  </svg>
);

const SuccessMsgIcon: React.FC = () => (
  <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true" className="flex-shrink-0">
    <circle cx="6" cy="6" r="5.25" stroke="currentColor" strokeWidth="1.5" />
    <path d="M4 6l1.5 1.5L8 5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

const InfoMsgIcon: React.FC = () => (
  <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true" className="flex-shrink-0">
    <circle cx="6" cy="6" r="5.25" stroke="currentColor" strokeWidth="1.5" />
    <path d="M6 5.5v3M6 3.75v.25" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
  </svg>
);

export const InputField = forwardRef<HTMLInputElement, InputFieldProps>(
  (
    {
      label,
      status = 'default',
      errorMessage,
      successMessage,
      helperText,
      required = false,
      readOnly = false,
      readOnlyPlain = false,
      disabled = false,
      fullWidth = false,
      icon,
      onChange,
      className,
      id,
      ...rest
    },
    ref
  ) => {
    // Message priority: Error > Success > Helper
    const feedbackStatus =
      status === 'error' && errorMessage
        ? 'error'
        : status === 'success' && successMessage
          ? 'success'
          : helperText
            ? 'helper'
            : null;

    const feedbackMessage =
      feedbackStatus === 'error'
        ? errorMessage
        : feedbackStatus === 'success'
          ? successMessage
          : helperText;

    const feedbackId = feedbackMessage && id ? `${id}-feedback` : undefined;

    const fieldClasses = [
      FIELD_BASE,
      FIELD_STATUS[status],
      disabled ? 'bg-gray-50 text-gray-400 cursor-not-allowed pointer-events-none border-border hover:border-border' : '',
      readOnly && !readOnlyPlain ? 'bg-gray-50 text-gray-600 cursor-default select-all hover:border-border' : '',
    ]
      .filter(Boolean)
      .join(' ');

    const messageColorClass =
      feedbackStatus === 'error'
        ? 'text-error'
        : feedbackStatus === 'success'
          ? 'text-success'
          : 'text-gray-400';

    return (
      <div className={cn('flex flex-col gap-1.5', fullWidth ? 'w-full' : 'inline-flex min-w-[180px]', className)}>
        {/* Label: 13px Regular, gray-600 (disabled gray-400) */}
        {label && (
          <label
            htmlFor={id}
            className={cn('text-sm-regular font-sans', disabled ? 'text-gray-400' : 'text-gray-600')}
          >
            {label}
            {required && (
              <span className="ml-0.5 text-error" aria-hidden="true">
                *
              </span>
            )}
          </label>
        )}

        {/* Input field: 36px */}
        <div className="relative">
          <input
            ref={ref}
            id={id}
            className={cn(fieldClasses, (status !== 'default' || icon) && 'pr-10')}
            disabled={disabled}
            readOnly={readOnly}
            aria-invalid={status === 'error'}
            aria-required={required}
            aria-describedby={feedbackId}
            onChange={(e) => onChange?.(e.target.value)}
            {...rest}
          />
          {status === 'error' && !disabled && (
            <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-error">
              <ErrorIcon />
            </span>
          )}
          {status === 'success' && !disabled && (
            <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-success">
              <SuccessIcon />
            </span>
          )}
          {status === 'default' && icon && (
            <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-gray-400">
              {icon}
            </span>
          )}
        </div>

        {/* Feedback message (12px icon + text) */}
        {feedbackMessage && (
          <div id={feedbackId} className={cn('flex items-center gap-1 text-xs-regular font-sans', messageColorClass)}>
            {feedbackStatus === 'error' && <ErrorMsgIcon />}
            {feedbackStatus === 'success' && <SuccessMsgIcon />}
            {feedbackStatus === 'helper' && <InfoMsgIcon />}
            <span>{feedbackMessage}</span>
          </div>
        )}
      </div>
    );
  }
);

InputField.displayName = 'InputField';
