import React, { forwardRef, useRef, useState } from 'react';
import type { SearchProps } from './Search.types';
import { cn } from '../../internal/cn';
import { Icon } from '../Icon';

/* ============================================
 * Search
 * Figma Source: 03_Components > Search
 *
 * Size: 36px · rounded-8 · 우측 아이콘 20px(Material Symbols)
 * States: Default · Hover · Focus · Filled
 *
 * 아이콘 동작(UX 추가, Figma 미정의):
 *   - 입력값 없음 → search 아이콘(장식)
 *   - 입력값 있음 → cancel 아이콘(동그라미 안 X) 버튼 → 클릭 시 검색어 비우기
 *
 * Figma 토큰:
 *   label 13px Regular gray-600 · border default → hover primary(#263949)
 *   focus 중립 border + ring 3px rgba(38,57,73,0.08) · text gray-950 · placeholder gray-400
 * ============================================ */

const FIELD =
  'w-full h-9 pl-3 pr-10 text-base-regular rounded-[8px] border border-border bg-surface text-gray-950 font-sans ' +
  'placeholder:text-gray-400 transition-all duration-200 outline-none ' +
  'hover:border-primary focus:shadow-[0_0_0_3px_rgba(38,57,73,0.08)]';

function setRef<T>(ref: React.Ref<T> | undefined, value: T | null) {
  if (typeof ref === 'function') ref(value);
  else if (ref && typeof ref === 'object') (ref as React.MutableRefObject<T | null>).current = value;
}

export const Search = forwardRef<HTMLInputElement, SearchProps>(
  (
    {
      label,
      disabled = false,
      fullWidth = false,
      placeholder = '검색어를 입력하세요',
      value,
      defaultValue,
      onChange,
      className,
      id,
      ...rest
    },
    ref
  ) => {
    const innerRef = useRef<HTMLInputElement | null>(null);
    const isControlled = value !== undefined;
    const [internalHas, setInternalHas] = useState(!!defaultValue);
    const hasText = isControlled ? !!value : internalHas;

    const handleClear = () => {
      const el = innerRef.current;
      if (el && !isControlled) {
        el.value = '';
        setInternalHas(false);
      }
      onChange?.('');
      el?.focus();
    };

    return (
      <div className={cn('flex flex-col gap-1.5', fullWidth && 'w-full', className)}>
        {label && (
          <label htmlFor={id} className="text-sm-regular font-sans text-gray-600">
            {label}
          </label>
        )}
        <div className="relative">
          <input
            ref={(node) => {
              setRef(innerRef, node);
              setRef(ref, node);
            }}
            id={id}
            type="text"
            placeholder={placeholder}
            disabled={disabled}
            value={value}
            defaultValue={defaultValue}
            className={cn(
              FIELD,
              disabled && 'bg-gray-50 text-gray-400 cursor-not-allowed pointer-events-none hover:border-border'
            )}
            onChange={(e) => {
              if (!isControlled) setInternalHas(!!e.target.value);
              onChange?.(e.target.value);
            }}
            {...rest}
          />
          {hasText && !disabled ? (
            <button
              type="button"
              onClick={handleClear}
              aria-label="검색어 지우기"
              className="absolute right-3 top-1/2 -translate-y-1/2 flex text-gray-400 hover:text-gray-600 transition-colors cursor-pointer"
            >
              <Icon name="cancel" size={20} filled decorative />
            </button>
          ) : (
            <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 flex text-gray-400">
              <Icon name="search" size={20} decorative />
            </span>
          )}
        </div>
      </div>
    );
  }
);

Search.displayName = 'Search';
