import { forwardRef, type CSSProperties } from 'react';
import { Box } from './Box';
import { cn } from '../../internal/cn';
import type { GridProps } from './Grid.types';
import type { SpacingToken } from './layout.types';

const GAP: Record<SpacingToken, string> = {
  0: 'gap-0', 4: 'gap-1', 8: 'gap-2', 12: 'gap-3', 16: 'gap-4',
  24: 'gap-6', 32: 'gap-8', 48: 'gap-12', 64: 'gap-16',
};
const ROW_GAP: Record<SpacingToken, string> = {
  0: 'gap-y-0', 4: 'gap-y-1', 8: 'gap-y-2', 12: 'gap-y-3', 16: 'gap-y-4',
  24: 'gap-y-6', 32: 'gap-y-8', 48: 'gap-y-12', 64: 'gap-y-16',
};
const COL_GAP: Record<SpacingToken, string> = {
  0: 'gap-x-0', 4: 'gap-x-1', 8: 'gap-x-2', 12: 'gap-x-3', 16: 'gap-x-4',
  24: 'gap-x-6', 32: 'gap-x-8', 48: 'gap-x-12', 64: 'gap-x-16',
};

const toTemplate = (value: number | string) =>
  typeof value === 'number' ? `repeat(${value}, minmax(0, 1fr))` : value;

export const Grid = forwardRef<HTMLElement, GridProps>(function Grid(
  { columns, rows, gap, rowGap, columnGap, areas, center, className, style, ...rest },
  ref
) {
  const gridStyle: CSSProperties = {
    ...(columns !== undefined && { gridTemplateColumns: toTemplate(columns) }),
    ...(rows !== undefined && { gridTemplateRows: toTemplate(rows) }),
    ...(areas !== undefined && {
      gridTemplateAreas: areas.map((row) => `"${row}"`).join(' '),
    }),
    ...style,
  };

  const classes = cn(
    'grid',
    gap !== undefined && GAP[gap],
    rowGap !== undefined && ROW_GAP[rowGap],
    columnGap !== undefined && COL_GAP[columnGap],
    center && 'place-items-center',
    className
  );

  return <Box ref={ref} className={classes} style={gridStyle} {...rest} />;
});
