import React from 'react';
import type { HTMLAttributes, ReactNode } from 'react';
import { cn } from '../../internal/cn';

/* ============================================
 * InlineAlert
 * Figma Source: 03_Components > InlineAlert
 *
 * 박스형 인라인 알림 — border + subtle bg + 아이콘 20px + 메시지(13 Medium).
 * status: warning | success | error
 *
 * Figma 토큰:
 *   warning: bg warning-subtle / border·text·icon warning(#d97706) / alert 아이콘
 *   success: bg success-subtle / border·text·icon success(#16a34a) / check_circle
 *   error:   bg error-subtle   / border·text·icon error(#dc2626)   / alert 아이콘
 *   box: rounded-8, p-17, icon-text gap 4
 * ============================================ */

export interface InlineAlertProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  status?: 'warning' | 'success' | 'error';
  /** 아이콘 직접 지정 (미지정 시 status 기본 아이콘) */
  icon?: ReactNode;
  children: ReactNode;
}

const STATUS: Record<NonNullable<InlineAlertProps['status']>, string> = {
  warning: 'bg-warning-subtle border-warning text-warning',
  success: 'bg-success-subtle border-success text-success',
  error: 'bg-error-subtle border-error text-error',
};

const AlertIcon: React.FC = () => (
  <svg width="20" height="20" viewBox="0 0 20 20" fill="none" aria-hidden="true" className="flex-shrink-0">
    <circle cx="10" cy="10" r="8.25" stroke="currentColor" strokeWidth="1.5" />
    <path d="M10 6v5M10 13.5v.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
  </svg>
);

const CheckCircleIcon: React.FC = () => (
  <svg width="20" height="20" viewBox="0 0 20 20" fill="none" aria-hidden="true" className="flex-shrink-0">
    <circle cx="10" cy="10" r="8.25" stroke="currentColor" strokeWidth="1.5" />
    <path d="M6.5 10l2.5 2.5L14 7" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

export const InlineAlert: React.FC<InlineAlertProps> = ({
  status = 'warning',
  icon,
  children,
  className,
  ...rest
}) => {
  const defaultIcon = status === 'success' ? <CheckCircleIcon /> : <AlertIcon />;
  return (
    <div
      role="alert"
      className={cn('flex items-start gap-1 rounded-[8px] border p-[17px] font-sans', STATUS[status], className)}
      {...rest}
    >
      <span aria-hidden="true" className="flex">
        {icon ?? defaultIcon}
      </span>
      <span className="text-sm-medium">{children}</span>
    </div>
  );
};

InlineAlert.displayName = 'InlineAlert';
