import { useEffect, useState } from 'react';
import { Modal } from './Modal';
import { useModalStore } from './modalStore';

/* ============================================
 * ModalRoot — imperative 모달 렌더 루트
 *
 * 앱 최상단에 한 번만 마운트한다. `modal.open(...)` 으로 쌓인 스택을
 * 각각 선언형 <Modal open ...> 로 렌더한다.
 * (각 <Modal> 이 자체적으로 createPortal(document.body) 하므로 별도 portal 불필요.
 *  DOM 순서상 나중 항목이 위에 쌓인다 — 모두 IDS_Z_INDEX.MODAL 동일, 후행 요소가 상위 페인트.)
 * ============================================ */

export const ModalRoot = () => {
  const stack = useModalStore((s) => s.stack);
  const closeById = useModalStore((s) => s.closeById);
  const [mounted, setMounted] = useState(false);

  useEffect(() => setMounted(true), []);
  if (!mounted || stack.length === 0) return null;

  return (
    <>
      {stack.map((entry) => {
        const { content, onClose: optionsOnClose, ...rest } = entry.options;
        return (
          <Modal
            key={entry.id}
            {...rest}
            open
            onClose={() => {
              optionsOnClose?.();
              closeById(entry.id);
            }}
          >
            {content}
          </Modal>
        );
      })}
    </>
  );
};

ModalRoot.displayName = 'ModalRoot';
export default ModalRoot;
