import React, { InputHTMLAttributes, createContext, useContext, forwardRef } from 'react';
import { cn } from '../../internal/cn';

/* ============================================
 * Radio (라디오 버튼)
 * Figma Source: 03_Components > radio
 * (props 는 staff Radio 와 동일 — drop-in 대체용)
 *
 * Sizes: default(18px, dot 8) | sm(16px, dot 6)
 * Figma 토큰:
 *   미선택 원 border gray-200 · 선택 원 primary + dot primary
 *   라벨 14px: 선택=SemiBold gray-950 / 미선택=Regular gray-950 / disabled=Regular gray-400
 *   circle-label gap 8
 * ============================================ */

type RadioSize = 'default' | 'sm';

interface RadioGroupContextValue {
  name?: string;
  value?: string;
  onChange?: (value: string) => void;
  size?: RadioSize;
  disabled?: boolean;
}

const RadioGroupContext = createContext<RadioGroupContextValue | null>(null);

export interface RadioProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size' | 'onChange' | 'type'> {
  /** 라벨 텍스트 */
  label?: React.ReactNode;
  /** 값 */
  value: string;
  /** 크기 */
  size?: RadioSize;
  /** 선택 변경 핸들러 (RadioGroup 미사용 시) */
  onChange?: (value: string) => void;
}

export const Radio = forwardRef<HTMLInputElement, RadioProps>(
  (
    {
      label,
      value,
      size: sizeProp,
      checked: checkedProp,
      disabled: disabledProp,
      onChange,
      name: nameProp,
      className,
      id,
      ...rest
    },
    ref
  ) => {
    const group = useContext(RadioGroupContext);

    const size = sizeProp ?? group?.size ?? 'default';
    const name = nameProp ?? group?.name;
    const disabled = disabledProp ?? group?.disabled ?? false;
    const checked = group ? group.value === value : checkedProp;

    const handleChange = () => {
      if (disabled) return;
      if (group?.onChange) group.onChange(value);
      else if (onChange) onChange(value);
    };

    const dim = size === 'sm' ? 'w-4 h-4' : 'w-[18px] h-[18px]';
    const dotDim = size === 'sm' ? 'w-1.5 h-1.5' : 'w-2 h-2';

    return (
      <label
        className={cn(
          'inline-flex items-center gap-2 font-sans',
          disabled ? 'cursor-not-allowed' : 'cursor-pointer',
          className
        )}
      >
        <span className="relative inline-flex items-center justify-center flex-shrink-0">
          <input
            ref={ref}
            type="radio"
            id={id}
            name={name}
            value={value}
            checked={checked}
            disabled={disabled}
            onChange={handleChange}
            className="peer sr-only"
            {...rest}
          />
          {/* Circle */}
          <span
            aria-hidden="true"
            className={cn(
              dim,
              'rounded-full border bg-surface transition-colors duration-150',
              checked
                ? 'border-primary peer-hover:border-primary-hover'
                : 'border-gray-200 peer-hover:bg-surface-muted',
              'peer-focus-visible:shadow-[0_0_0_3px_rgba(38,57,73,0.08)]'
            )}
          />
          {/* Inner dot */}
          {checked && (
            <span
              aria-hidden="true"
              className={cn('absolute rounded-full', dotDim, disabled ? 'bg-gray-300' : 'bg-primary')}
            />
          )}
        </span>
        {label !== undefined && (
          <span
            className={cn(
              checked ? 'text-base-semibold' : 'text-base-regular',
              disabled ? 'text-gray-400' : 'text-gray-950'
            )}
          >
            {label}
          </span>
        )}
      </label>
    );
  }
);

Radio.displayName = 'Radio';

/* ── RadioGroup ── */
export interface RadioGroupProps {
  name: string;
  value?: string;
  onChange?: (value: string) => void;
  size?: RadioSize;
  disabled?: boolean;
  orientation?: 'vertical' | 'horizontal';
  'aria-label'?: string;
  children: React.ReactNode;
  className?: string;
}

export const RadioGroup: React.FC<RadioGroupProps> = ({
  name,
  value,
  onChange,
  size = 'default',
  disabled = false,
  orientation = 'vertical',
  'aria-label': ariaLabel,
  children,
  className,
}) => {
  return (
    <RadioGroupContext.Provider value={{ name, value, onChange, size, disabled }}>
      <div
        role="radiogroup"
        aria-label={ariaLabel}
        className={cn('flex', orientation === 'vertical' ? 'flex-col gap-4' : 'flex-row gap-6', className)}
      >
        {children}
      </div>
    </RadioGroupContext.Provider>
  );
};

RadioGroup.displayName = 'RadioGroup';
