import React from 'react';
import { Select } from '../Select';
import type { PaginationProps } from './Pagination.types';

/* ============================================
 * Pagination
 * Figma Source: 03_Components > Pagination
 * (props 는 staff Pagination 과 동일 — drop-in 대체용)
 *
 * navPlacement:
 *   split (기본): 이전 │ 1 2 3 … 20 │ 다음  (숫자 양옆)
 *   end:          1 2 3 … 20  …  이전 다음 (숫자 왼쪽, 이전·다음 오른쪽 묶음)
 *
 * Figma 토큰:
 *   페이지번호 14 Regular gray-950, active bg primary text white, rounded-8
 *   nav 텍스트 gray-600(active)/gray-300(disabled) · ellipsis gray-400
 * ============================================ */

function getPageNumbers(current: number, total: number, max: number): (number | 'ellipsis')[] {
  if (total <= max) return Array.from({ length: total }, (_, i) => i + 1);
  const pages: (number | 'ellipsis')[] = [];
  const sideCount = Math.floor((max - 3) / 2);
  pages.push(1);
  const startPage = Math.max(2, current - sideCount);
  const endPage = Math.min(total - 1, current + sideCount);
  if (startPage > 2) pages.push('ellipsis');
  for (let i = startPage; i <= endPage; i++) pages.push(i);
  if (endPage < total - 1) pages.push('ellipsis');
  if (total > 1) pages.push(total);
  return pages;
}

export const Pagination: React.FC<PaginationProps> = ({
  currentPage,
  totalPages,
  onChange,
  size = 'default',
  pageSize,
  pageSizeOptions,
  onPageSizeChange,
  showFirstLast = false,
  maxButtons = 7,
  disabled = false,
  navPlacement = 'split',
  className,
}) => {
  const pages = getPageNumbers(currentPage, totalPages, maxButtons);
  const isDefault = size === 'default';
  const btnSize = isDefault ? 'w-9 h-9 text-base-regular' : 'w-8 h-8 text-xs-medium';
  const navBtnPad = isDefault ? 'px-3 h-9 text-base-medium' : 'px-2 h-8 text-xs-medium';

  const hasPrev = currentPage > 1;
  const hasNext = currentPage < totalPages;

  const navBtn = (enabled: boolean) =>
    [
      'flex items-center justify-center gap-1 rounded-[8px] transition-colors',
      navBtnPad,
      enabled ? 'text-gray-600 hover:bg-surface-muted hover:text-gray-950 cursor-pointer' : 'text-gray-300 cursor-not-allowed',
    ].join(' ');

  const FirstBtn = showFirstLast ? (
    <button type="button" disabled={!hasPrev || disabled} onClick={() => onChange(1)} className={navBtn(hasPrev)}>
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M7 4L3 8l4 4M13 4L9 8l4 4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
    </button>
  ) : null;

  const PrevBtn = (
    <button type="button" disabled={!hasPrev || disabled} onClick={() => onChange(currentPage - 1)} className={navBtn(hasPrev)}>
      <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true"><path d="M11 5L7 9l4 4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
      이전
    </button>
  );

  const NextBtn = (
    <button type="button" disabled={!hasNext || disabled} onClick={() => onChange(currentPage + 1)} className={navBtn(hasNext)}>
      다음
      <svg width="18" height="18" viewBox="0 0 18 18" fill="none" aria-hidden="true"><path d="M7 5l4 4-4 4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
    </button>
  );

  const LastBtn = showFirstLast ? (
    <button type="button" disabled={!hasNext || disabled} onClick={() => onChange(totalPages)} className={navBtn(hasNext)}>
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M3 4l4 4-4 4M9 4l4 4-4 4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
    </button>
  ) : null;

  const Numbers = (
    <div className="flex items-center gap-1">
      {pages.map((page, i) =>
        page === 'ellipsis' ? (
          <span key={`ellipsis-${i}`} className={['flex items-center justify-center text-gray-400', btnSize].join(' ')}>...</span>
        ) : (
          <button
            key={page}
            type="button"
            disabled={disabled}
            onClick={() => onChange(page)}
            className={[
              'flex items-center justify-center rounded-[8px] transition-colors',
              btnSize,
              page === currentPage ? 'bg-primary text-white' : 'text-gray-950 hover:bg-surface-muted cursor-pointer',
            ].join(' ')}
          >
            {page}
          </button>
        )
      )}
    </div>
  );

  const PageSize =
    pageSizeOptions && onPageSizeChange && pageSize ? (
      <div className="flex items-center gap-2">
        <span className="text-base-regular text-gray-600">페이지당</span>
        <Select
          options={pageSizeOptions.map((opt) => ({ value: String(opt), label: String(opt) }))}
          value={String(pageSize)}
          onChange={(v) => onPageSizeChange(Number(v))}
          className="min-w-0 w-[72px]"
        />
        <span className="text-base-regular text-gray-600">행</span>
      </div>
    ) : null;

  return (
    <div
      className={[
        'flex items-center justify-between font-sans py-4',
        disabled && 'opacity-50 pointer-events-none',
        className,
      ].filter(Boolean).join(' ')}
    >
      {navPlacement === 'end' ? (
        <>
          {/* 좌측: 페이지당 */}
          <div className="flex items-center gap-3">{PageSize}</div>
          {/* 우측: 숫자 + 이전·다음 (붙어있음) */}
          <div className="flex items-center gap-1">
            {Numbers}
            {FirstBtn}
            {PrevBtn}
            {NextBtn}
            {LastBtn}
          </div>
        </>
      ) : (
        <>
          {/* 좌측: 페이지당 */}
          <div className="flex items-center gap-3">{PageSize}</div>
          {/* 우측: 이전 │ 숫자 │ 다음 */}
          <div className="flex items-center gap-1">
            {FirstBtn}
            {PrevBtn}
            {Numbers}
            {NextBtn}
            {LastBtn}
          </div>
        </>
      )}
    </div>
  );
};

Pagination.displayName = 'Pagination';
