import { forwardRef } from 'react';
import { Box } from './Box';
import { cn } from '../../internal/cn';
import type { StackAlign, StackDirection, StackJustify, StackProps } from './Stack.types';
import type { SpacingToken } from './layout.types';

const DIR: Record<StackDirection, string> = {
  row: 'flex-row',
  column: 'flex-col',
};

const ALIGN: Record<StackAlign, string> = {
  start: 'items-start',
  center: 'items-center',
  end: 'items-end',
  stretch: 'items-stretch',
  baseline: 'items-baseline',
};

const JUSTIFY: Record<StackJustify, string> = {
  start: 'justify-start',
  center: 'justify-center',
  end: 'justify-end',
  between: 'justify-between',
  around: 'justify-around',
  evenly: 'justify-evenly',
};

const GAP: Record<SpacingToken, string> = {
  0: 'gap-0', 4: 'gap-1', 8: 'gap-2', 12: 'gap-3', 16: 'gap-4',
  24: 'gap-6', 32: 'gap-8', 48: 'gap-12', 64: 'gap-16',
};

export const Stack = forwardRef<HTMLElement, StackProps>(function Stack(
  { direction = 'column', gap, align, justify, wrap, center, className, ...rest },
  ref
) {
  const effectiveAlign = center ? 'center' : align;
  const effectiveJustify = center ? 'center' : justify;

  const classes = cn(
    'flex',
    DIR[direction],
    gap !== undefined && GAP[gap],
    effectiveAlign && ALIGN[effectiveAlign],
    effectiveJustify && JUSTIFY[effectiveJustify],
    wrap && 'flex-wrap',
    className
  );
  return <Box ref={ref} className={classes} {...rest} />;
});
