import React from 'react';

/* ============================================
 * Icon
 *
 * Component Name: Icon
 * Figma Source: 02_Icons_Split
 *
 * 역할: B2B Admin 공통 아이콘 래퍼 컴포넌트
 *       Google Material Icons Outlined 기반
 *
 * Props:
 *   name        — 아이콘 이름 (Material Icons 기준)
 *   size        — 16 | 20 | 24 | 32 (Figma Size Scale 기준)
 *   color       — CSS variable 문자열 (semantic token만 허용)
 *   decorative  — 장식용 아이콘 (aria-hidden)
 *   ariaLabel   — 접근성 라벨 (icon-only 버튼 필수)
 *   className   — 추가 Tailwind 클래스
 *
 * Size Scale (Figma 확인):
 *   16px → Status indicator, Inline validation, Badge icon
 *   20px → Input prefix/suffix, Select dropdown, Small button (Default)
 *   24px → Button icon, Tab icon, Navigation, Default action
 *   32px → Empty state, Error page, Section emphasis
 * ============================================ */

export type IconSize = 16 | 20 | 24 | 32 | 48;

export interface IconProps {
  /** 아이콘 이름 (Material Icons name) */
  name: string;
  /** 아이콘 크기 (16 | 20 | 24 | 32) */
  size?: IconSize;
  /** 색상 — semantic token CSS variable만 사용 (e.g. 'var(--text)') */
  color?: string;
  /** 채워진(FILL=1) 아이콘 — 예: cancel(회색 원+X), 활성 탭 아이콘 */
  filled?: boolean;
  /** 장식용 아이콘 (스크린리더 제외) */
  decorative?: boolean;
  /** 접근성 라벨 (icon-only 버튼 필수) */
  ariaLabel?: string;
  /** 추가 Tailwind 클래스 */
  className?: string;
}

const SIZE_CLASS: Record<IconSize, string> = {
  16: 'w-4 h-4',
  20: 'w-5 h-5',
  24: 'w-6 h-6',
  32: 'w-8 h-8',
  48: 'w-12 h-12',
};

export const Icon: React.FC<IconProps> = ({
  name,
  size = 20,
  color,
  filled = false,
  decorative = false,
  ariaLabel,
  className,
}) => {
  if (process.env.NODE_ENV === 'development' && !decorative && !ariaLabel) {
    console.warn(
      `[Icon] "${name}": decorative가 아닌 아이콘은 ariaLabel이 필요합니다.`
    );
  }

  return (
    <span
      className={['inline-flex items-center justify-center flex-shrink-0 overflow-hidden', SIZE_CLASS[size], className]
        .filter(Boolean)
        .join(' ')}
      style={color ? { color } : undefined}
      role={decorative ? undefined : 'img'}
      aria-hidden={decorative ? true : undefined}
      aria-label={!decorative ? ariaLabel : undefined}
    >
      <span
        className="material-symbols-outlined leading-none select-none"
        style={{ fontSize: size, fontVariationSettings: filled ? "'FILL' 1" : undefined }}
        aria-hidden="true"
      >
        {name}
      </span>
    </span>
  );
};

export default Icon;
